import { createAdminClient, authenticateUser, requireInternalSecret } from '../_shared/amazon/supabase.ts';
import { shopifyAccountCredentials, shopifyStoredApplicationCredentials, shopifyError } from '../_shared/shopifyAuth.ts';
import { normalizeShopifyAnalyticsOrder, shopifyAnalyticsCallerAllowed } from '../_shared/shopifyAnalyticsFinance.ts';
const headers={'Access-Control-Allow-Origin':'*','Access-Control-Allow-Headers':'authorization, x-client-info, apikey, content-type','Access-Control-Allow-Methods':'POST, OPTIONS','Content-Type':'application/json'};
const reply=(data:unknown,status=200)=>new Response(JSON.stringify(data),{headers,status});
const money='shopMoney { amount currencyCode }';
const pageInfo='pageInfo { hasNextPage endCursor }';
const lineFields=`id name sku quantity requiresShipping variant {id} image {url} originalTotalSet {${money}} discountAllocations {allocatedAmountSet {${money}}} discountedTotalSet {${money}} taxLines {priceSet {${money}}}`;
const refundLineFields=`quantity subtotalSet {${money}} totalTaxSet {${money}} lineItem {id sku variant {id}}`;
const transactionFields='status kind';
const refundShippingFields=`taxAmountSet {${money}}`;
const adjustmentFields=`taxAmountSet {${money}}`;
const refundFields=`id createdAt totalRefundedSet {${money}} transactions(first:100) {${pageInfo} nodes {${transactionFields}}} refundLineItems(first:100) {${pageInfo} nodes {${refundLineFields}}} refundShippingLines(first:100) {${pageInfo} nodes {${refundShippingFields}}} orderAdjustments(first:100) {${pageInfo} nodes {${adjustmentFields}}}`;
const orderFields=`id legacyResourceId createdAt processedAt updatedAt cancelledAt test taxesIncluded displayFinancialStatus totalPriceSet {${money}} totalTaxSet {${money}} totalDiscountsSet {${money}} totalShippingPriceSet {${money}} lineItems(first:100) {${pageInfo} nodes {${lineFields}}} refunds {id}`;
async function gql(c:any,query:string,variables:Record<string,unknown>={}){
 for(let attempt=0;attempt<5;attempt++){
  const r=await fetch(`https://${c.shopDomain}/admin/api/${c.apiVersion}/graphql.json`,{method:'POST',headers:{'Content-Type':'application/json','X-Shopify-Access-Token':c.accessToken},body:JSON.stringify({query,variables}),signal:AbortSignal.timeout(25000),redirect:'error'});
  const p=await r.json().catch(()=>({}));
  if(r.status===429||p.errors?.some((e:any)=>e.extensions?.code==='THROTTLED')){await new Promise(resolve=>setTimeout(resolve,Math.min(5000,1000*2**attempt)));continue;}
  if(!r.ok||p.errors?.length)throw new Error(`Shopify (${r.status}): ${p.errors?.map((e:any)=>e.message).join(' · ')||'No se pudo consultar la tienda.'}`);
  return p.data;
 }
 throw new Error('Shopify limita temporalmente las consultas. Vuelve a sincronizar.');
}
async function complete(c:any,node:any,field:string,fields:string,type='Order'){
 const connection=node[field];if(!connection)return;
 while(connection.pageInfo?.hasNextPage){
  const data=await gql(c,`query($id:ID!,$after:String){node(id:$id){... on ${type}{${field}(first:100,after:$after){${pageInfo} nodes{${fields}}}}}}`,{id:node.id,after:connection.pageInfo.endCursor});
  const next=data.node?.[field];if(!next)throw new Error('Shopify no devolvió una página financiera completa.');
  connection.nodes.push(...next.nodes);connection.pageInfo=next.pageInfo;
 }
}
async function save(admin:any,table:string,rows:any[],onConflict:string){
 if(!rows.length)return;
 const r=await admin.from(table).upsert(rows,{onConflict});if(r.error)throw r.error;
}
async function syncStore(admin:any,account:any,history:boolean){
 const owner=account.owner_id,store=account.id,lease=crypto.randomUUID();
 const claimed=await admin.rpc('shopify_analytics_claim_sync',{owner,store,lease});if(claimed.error)throw claimed.error;
 if(!claimed.data)return {id:store,name:account.display_name,synced:0,skipped:true};
 const leaseStarted=Date.now();
 const updateState=async(row:any)=>{const result=await admin.from('shopify_analytics_sync_state').update(row).eq('owner_id',owner).eq('integration_account_id',store).eq('sync_lease',lease);if(result.error)throw result.error;};
 try{
 const {data:state,error:stateError}=await admin.from('shopify_analytics_sync_state').select('*').eq('integration_account_id',store).maybeSingle();if(stateError)throw stateError;
 await updateState({status:'syncing',error:null});
 const c=await shopifyAccountCredentials(admin,account,await shopifyStoredApplicationCredentials(admin,owner));
  const scopeData=await gql(c,'{currentAppInstallation{accessScopes{handle}}}');
  const scopes=new Set<string>((scopeData.currentAppInstallation?.accessScopes||[]).map((s:any)=>s.handle));
  const catalogAvailable=scopes.has('read_products')||scopes.has('write_products');
  const inventoryAvailable=catalogAvailable&&(scopes.has('read_inventory')||scopes.has('write_inventory'));
  let variantsAccessible=true;
  let scopedLineFields=lineFields;
  let scopedRefundLineFields=refundLineFields;
  let scopedOrderFields=orderFields;
  let scopedRefundFields=refundFields;
  const allHistory=history||!state?.last_synced_at||state?.history_complete===false;
  const changedAfter=state?.last_synced_at?new Date(new Date(state.last_synced_at).getTime()-2*86400000).toISOString():null;
  const query=allHistory?null:`updated_at:>=${changedAfter}`;
  let after:string|null=allHistory&&!history?state?.orders_cursor||null:null;
  let count=0;let hasNext=false;const started=Date.now();
  do{
   const data=await gql(c,`query($after:String,$query:String){orders(first:25,after:$after,sortKey:UPDATED_AT,query:$query){${pageInfo} nodes{id}}}`,{after,query});
   const connection=data.orders;
   for(const remote of connection.nodes){
    let full:any;
    try{full=await gql(c,`query($id:ID!){order(id:$id){${scopedOrderFields}}}`,{id:remote.id});}
    catch(error){
     if(!variantsAccessible||!/access denied.*variant|access.*read_products/i.test(shopifyError(error)))throw error;
     variantsAccessible=false;scopedLineFields=lineFields.replace('variant {id}','');scopedRefundLineFields=refundLineFields.replace('variant {id}','');scopedOrderFields=orderFields.replace('variant {id}','');scopedRefundFields=refundFields.replace('variant {id}','');
     full=await gql(c,`query($id:ID!){order(id:$id){${scopedOrderFields}}}`,{id:remote.id});
    }
    const order=full.order;if(!order)continue;
    await complete(c,order,'lineItems',scopedLineFields);
    for(let index=0;index<(order.refunds||[]).length;index++){
     const refundData=await gql(c,`query($id:ID!){refund(id:$id){${scopedRefundFields}}}`,{id:order.refunds[index].id});
     const refund=refundData.refund;if(!refund)throw new Error('Shopify no devolvió una devolución completa.');
     order.refunds[index]=refund;
     await complete(c,refund,'transactions',transactionFields,'Refund');
     await complete(c,refund,'refundLineItems',scopedRefundLineFields,'Refund');
     await complete(c,refund,'refundShippingLines',refundShippingFields,'Refund');
     await complete(c,refund,'orderAdjustments',adjustmentFields,'Refund');
    }
    const normalized=normalizeShopifyAnalyticsOrder(order,owner,store);
    const result=await admin.rpc('shopify_analytics_ingest',{snapshot:normalized,lease});if(result.error)throw result.error;count++;
   }
   after=connection.pageInfo.endCursor;hasNext=connection.pageInfo.hasNextPage;
   // Stop only after complete order pages; the next run resumes history at this cursor.
   if(allHistory&&hasNext&&Date.now()-started>70000)break;
  }while(hasNext);
  if(catalogAvailable&&!hasNext){
   const generation=crypto.randomUUID();
   let cursor:string|null=null;
   do{
    const fields=`id sku title image{url} product{title featuredImage{url}} ${inventoryAvailable?'inventoryQuantity inventoryItem{tracked}':''}`;
    const data=await gql(c,`query($after:String){productVariants(first:100,after:$after){${pageInfo} nodes{${fields}}}}`,{after:cursor});
    const connection=data.productVariants;
    const rows=connection.nodes.map((variant:any)=>({owner_id:owner,integration_account_id:store,variant_id:variant.id,seller_sku:variant.sku||variant.id,name:[variant.product?.title,variant.title==='Default Title'?null:variant.title].filter(Boolean).join(' · '),image_url:variant.image?.url||variant.product?.featuredImage?.url||null,inventory_quantity:inventoryAvailable&&variant.inventoryItem?.tracked?variant.inventoryQuantity:null,sync_generation:generation}));
    const saved=await admin.rpc('shopify_analytics_catalog_batch',{owner,store,lease,rows});if(saved.error)throw saved.error;
    cursor=connection.pageInfo.hasNextPage?connection.pageInfo.endCursor:null;
   }while(cursor);
   const finished=await admin.rpc('shopify_analytics_finish_catalog',{owner,store,generation,lease});if(finished.error)throw finished.error;
  }
  if(Date.now()-leaseStarted>240000)throw new Error('La sincronización excedió el tiempo permitido. Vuelve a sincronizar.');
  if(!inventoryAvailable){const result=await admin.rpc('shopify_analytics_invalidate_inventory',{owner,store,lease});if(result.error)throw result.error;}
  const {data:earliest,error:earliestError}=await admin.from('shopify_analytics_orders').select('event_at').eq('owner_id',owner).eq('integration_account_id',store).order('event_at').limit(1);if(earliestError)throw earliestError;
  await updateState({status:hasNext?'partial':'ready',last_synced_at:hasNext?state?.last_synced_at||null:new Date().toISOString(),available_from:earliest?.[0]?.event_at||null,inventory_available:inventoryAvailable,catalog_available:catalogAvailable,history_limited:!scopes.has('read_all_orders'),orders_cursor:allHistory&&hasNext?after:null,history_complete:!hasNext,error:hasNext?'Importación histórica en curso; continuará automáticamente.':null});
  return {id:store,name:account.display_name,synced:count,partial:hasNext,inventoryAvailable,catalogAvailable};
 }catch(error){
  const message=shopifyError(error);await updateState({status:'error',error:message.slice(0,900)});
  return {id:store,name:account.display_name,synced:0,error:message};
 }finally{await admin.rpc('shopify_analytics_release_sync',{owner,store,lease});}
}
Deno.serve(async(req:Request)=>{
 if(req.method==='OPTIONS')return reply({ok:true});if(req.method!=='POST')return reply({error:'Método no permitido.'},405);
 const admin=createAdminClient();
 try{
  const body=await req.json().catch(()=>({}));let owner:string;
  if(body.ownerId){requireInternalSecret(req);owner=String(body.ownerId);}
  else{const caller=await authenticateUser(req,admin);if(!shopifyAnalyticsCallerAllowed(caller))return reply({error:'No tienes permiso de Shopify.'},403);owner=caller.data_owner_id;}
  let q=admin.from('integration_accounts').select('*').eq('owner_id',owner).eq('provider','shopify').eq('enabled',true).neq('status','disabled').neq('credential_source','derived');
  if(body.integrationAccountId)q=q.eq('id',body.integrationAccountId);
  const {data:accounts,error}=await q;if(error)throw error;
  const results=[];for(const a of accounts||[])results.push(await syncStore(admin,a,Boolean(body.history)));
  return reply({ok:results.every(r=>!r.error),configured:Boolean(accounts?.length),synced:results.reduce((n,r)=>n+r.synced,0),stores:results.length,errors:results.filter(r=>'error' in r),accounts:results});
 }catch(error){return reply({error:shopifyError(error)},String(shopifyError(error)).includes('Sesión')||String(shopifyError(error)).includes('autorizada')?401:403);}
});

import { createClient } from 'npm:@supabase/supabase-js@2';

export type AppCaller={
  user_id:string;
  data_owner_id:string;
  role:string;
  active:boolean;
  permissions:string[]|null;
};

export function getAdminKey(){
  const secretKeys=Deno.env.get('SUPABASE_SECRET_KEYS');
  if(secretKeys){
    try{
      const parsed=JSON.parse(secretKeys);
      if(typeof parsed?.default==='string'&&parsed.default.trim())return parsed.default.trim();
    }catch{/* legacy fallback below */}
  }
  return (Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')||'').trim();
}

export function createAdminClient(){
  const url=(Deno.env.get('SUPABASE_URL')||'').trim();
  const key=getAdminKey();
  if(!url||!key)throw new Error('Configuración interna de Supabase no disponible.');
  return createClient(url,key,{auth:{persistSession:false,autoRefreshToken:false}});
}

export function requireInternalSecret(req:Request){
  const expected=getAdminKey();
  const presented=(req.headers.get('apikey')||'').trim();
  if(!expected||!presented||presented!==expected)throw new Error('Llamada interna no autorizada.');
}

export async function authenticateUser(req:Request,admin:any):Promise<AppCaller>{
  const token=(req.headers.get('Authorization')||'').replace(/^Bearer\s+/i,'').trim();
  if(!token)throw new Error('Sesión no válida.');
  const {data:userData,error:userError}=await admin.auth.getUser(token);
  if(userError||!userData?.user)throw new Error('Sesión no válida.');
  const {data:caller,error}=await admin.from('app_users')
    .select('user_id,data_owner_id,role,active,permissions')
    .eq('user_id',userData.user.id)
    .maybeSingle();
  if(error)throw error;
  if(!caller?.active)throw new Error('Tu acceso está desactivado.');
  const {data:workspace,error:workspaceError}=await admin.from('workspaces').select('status').eq('id',caller.data_owner_id).maybeSingle();
  if(workspaceError)throw workspaceError;
  if(!workspace||!['active','trialing'].includes(workspace.status))throw new Error('El acceso de tu empresa está suspendido.');
  return caller as AppCaller;
}

export async function authenticateAdminUser(req:Request,admin:any){
  const caller=await authenticateUser(req,admin);
  if(caller.role!=='admin')throw new Error('Solo un administrador puede iniciar una sincronización manual de Amazon.');
  return caller;
}

export function shopifyError(error:unknown,fallback='No se pudo completar la conexión con Shopify.'):string{
  if(typeof error==='string'&&error.trim()&&error!=='[object Object]')return error.trim();
  if(error&&typeof error==='object'){
    const value=error as Record<string,unknown>;
    for(const key of ['message','error','error_description','details']){
      if(value[key]&&value[key]!==error){const detail=shopifyError(value[key],'');if(detail)return detail;}
    }
  }
  return fallback;
}

export function shopifyDomain(value:unknown){
  const domain=String(value??'').trim().toLowerCase().replace(/^https:\/\//,'').replace(/\/$/,'');
  if(!/^[a-z0-9][a-z0-9-]*\.myshopify\.com$/.test(domain))throw new Error('Indica el dominio permanente de Shopify: tienda.myshopify.com, sin rutas.');
  return domain;
}

export function shopifyLegacyCredentials(domain:unknown,accessToken:unknown){
  const token=String(accessToken??'').trim();
  if(!token)throw new Error('Indica el access token de la app antigua.');
  return {shopDomain:shopifyDomain(domain),accessToken:token,authMode:'token'};
}

export function shopifyApplicationCredentials(environment:any,configured:any){
  const candidate=environment?.clientId&&environment?.clientSecret?environment:configured;
  const clientId=String(candidate?.clientId||'').trim(),clientSecret=String(candidate?.clientSecret||'').trim();
  return {clientId,clientSecret,ready:Boolean(clientId&&clientSecret)};
}

export async function shopifyStoredApplicationCredentials(admin:any,ownerId:string){
  const environment={clientId:Deno.env.get('SHOPIFY_CLIENT_ID')||'',clientSecret:Deno.env.get('SHOPIFY_CLIENT_SECRET')||''};
  let configured={};
  if(!environment.clientId||!environment.clientSecret){
    const result=await admin.rpc('integration_read_named_secret',{p_name:`shopify-app:${ownerId}`});
    if(result.error)throw result.error;
    try{configured=JSON.parse(result.data||'{}')}catch{}
  }
  return shopifyApplicationCredentials(environment,configured);
}

export async function shopifyHash(value:string){
  return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)))).map(v=>v.toString(16).padStart(2,'0')).join('');
}

export async function verifyShopifyCallback(params:URLSearchParams,secret:string){
  const keys=[...params.keys()];
  if(new Set(keys).size!==keys.length)return false;
  const supplied=params.get('hmac')||'';
  if(!/^[a-f0-9]{64}$/.test(supplied))return false;
  const message=[...params.entries()].filter(([key])=>key!=='hmac').sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>`${k}=${v}`).join('&');
  const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret),{name:'HMAC',hash:'SHA-256'},false,['verify']);
  const signature=new Uint8Array(supplied.match(/../g)!.map(v=>parseInt(v,16)));
  return crypto.subtle.verify('HMAC',key,signature,new TextEncoder().encode(message));
}

export async function shopifyTokenRequest(domain:string,body:URLSearchParams){
  const res=await fetch(`https://${shopifyDomain(domain)}/admin/oauth/access_token`,{
    method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded',Accept:'application/json'},body,
    redirect:'error',signal:AbortSignal.timeout(20000),
  });
  const token=await res.json().catch(()=>({}));
  if(!res.ok||token.error)throw new Error(token.error==='invalid_client'?'Shopify no acepta el ID o secreto de la app. Comprueba sus credenciales.':token.error==='shop_not_permitted'?'La app y la tienda deben pertenecer a la misma organización Shopify. Para tiendas de clientes utiliza Autorizar con Shopify.':token.error==='invalid_grant'?'Shopify ha caducado o revocado la autorización. Vuelve a conectar la tienda.':`Shopify (${res.status}): no se pudo obtener la autorización. Comprueba que la app esté instalada y tenga permiso read_orders.`);
  return token;
}

export function shopifyTokenCredentials(stored:any,token:any,now=Date.now()){
  if(!token?.access_token)throw new Error('Shopify no devolvió un access token.');
  const grantedScopes=new Set(String(token.scope||'').split(/[\s,]+/).filter(Boolean));
  if(!grantedScopes.has('read_orders')&&!grantedScopes.has('write_orders'))throw new Error('La app necesita permiso read_orders o write_orders. Añádelo en Shopify y vuelve a autorizar.');
  if(token.expires_in!=null&&(!Number.isFinite(Number(token.expires_in))||Number(token.expires_in)<=0))throw new Error('Shopify devolvió una caducidad no válida.');
  return {...stored,accessToken:String(token.access_token),scope:String(token.scope),expiresAt:token.expires_in?now+Number(token.expires_in)*1000:null,...(token.refresh_token?{refreshToken:String(token.refresh_token)}:{})};
}

export async function resolveShopifyCredentials(stored:any,config:any,request=shopifyTokenRequest,persist?: (stored:any)=>Promise<unknown>){
  const domain=shopifyDomain(stored.shopDomain||stored.shop_domain||config.shopDomain);
  let token=String(stored.accessToken||stored.access_token||'').trim();
  if(!token||(stored.expiresAt&&Number(stored.expiresAt)<=Date.now()+300000)){
    const clientId=stored.clientId||Deno.env.get('SHOPIFY_CLIENT_ID');
    const clientSecret=stored.clientSecret||Deno.env.get('SHOPIFY_CLIENT_SECRET');
    if(!clientId||!clientSecret)throw new Error('Renueva la conexión con Shopify desde Integraciones.');
    const fields:Record<string,string>={client_id:clientId,client_secret:clientSecret};
    if(stored.authMode==='client_credentials')fields.grant_type='client_credentials';
    else if(stored.refreshToken){fields.grant_type='refresh_token';fields.refresh_token=stored.refreshToken;}
    else throw new Error('Renueva la autorización de Shopify desde Integraciones.');
    const renewed=shopifyTokenCredentials(stored,await request(domain,new URLSearchParams(fields)));
    if(persist)await persist(renewed);
    token=renewed.accessToken;
  }
  return {shopDomain:domain,accessToken:token,apiVersion:String(config.apiVersion||'2026-07')};
}

export async function shopifyAccountCredentials(admin:any,account:any,appCredentials?:{clientId:string;clientSecret:string}){
  async function read(){
    const result=await admin.from('integration_accounts').select('*').eq('id',account.id).eq('owner_id',account.owner_id).maybeSingle();
    if(result.error)throw result.error;
    if(!result.data?.enabled||result.data.status==='disabled')throw new Error('La cuenta Shopify está desconectada.');
    const secret=await admin.rpc('integration_read_secret',{p_secret_id:result.data.secret_id});
    if(secret.error)throw secret.error;
    return {row:result.data,stored:JSON.parse(secret.data||'{}')};
  }
  let current=await read();
  if(current.stored.accessToken&&(!current.stored.expiresAt||current.stored.expiresAt>Date.now()+300000))return resolveShopifyCredentials(current.stored,current.row.config||{});
  const lease=crypto.randomUUID();
  let claimed=false;
  for(let attempt=0;attempt<125;attempt++){
    const result=await admin.rpc('integration_shopify_claim_refresh',{p_account_id:account.id,p_owner_id:account.owner_id,p_lease:lease});
    if(result.error)throw result.error;
    if(result.data){claimed=true;break;}
    await new Promise(resolve=>setTimeout(resolve,200));
    current=await read();
    if(current.stored.accessToken&&(!current.stored.expiresAt||current.stored.expiresAt>Date.now()+300000))return resolveShopifyCredentials(current.stored,current.row.config||{});
  }
  if(!claimed)throw new Error('Shopify está renovando la autorización. Vuelve a intentarlo en unos segundos.');
  try{
    current=await read();
    if(current.stored.authMode==='oauth'&&appCredentials&&current.stored.clientId!==appCredentials.clientId)throw new Error('La app Shopify cambió. Vuelve a autorizar esta tienda.');
    const storedForRenewal=current.stored.authMode==='oauth'&&appCredentials?{...current.stored,clientSecret:appCredentials.clientSecret}:current.stored;
    return await resolveShopifyCredentials(storedForRenewal,current.row.config||{},shopifyTokenRequest,async stored=>{
      if(current.stored.authMode==='oauth')delete stored.clientSecret;
      const result=await admin.rpc('integration_shopify_commit_refresh',{p_account_id:account.id,p_owner_id:account.owner_id,p_lease:lease,p_version:current.row.shopify_credential_version,p_secret:JSON.stringify(stored)});
      if(result.error)throw result.error;
      if(!result.data)throw new Error('La conexión de Shopify cambió durante la renovación. Vuelve a intentarlo.');
    });
  }finally{
    await admin.rpc('integration_shopify_release_refresh',{p_account_id:account.id,p_owner_id:account.owner_id,p_lease:lease});
  }
}

export async function commitShopifyAuthorization(admin:any,account:any,pending:any,stored:any){
  const config={...(account.config||{}),shopDomain:stored.shopDomain,authMode:'oauth',syncOrders:pending.syncOrders!==false,apiVersion:'2026-07'};
  delete config.oauthStateHash;
  const result=await admin.rpc('integration_shopify_complete_oauth',{p_account_id:account.id,p_owner_id:account.owner_id,p_version:account.shopify_credential_version,p_secret:JSON.stringify(stored),p_display_name:pending.displayName||account.display_name,p_config:config});
  if(result.error)throw result.error;
  if(!result.data)throw new Error('La conexión de Shopify cambió mientras autorizabas. Vuelve a conectar la tienda.');
}

export async function verifyShopifyInstallLaunch(params:URLSearchParams,secret:string,now=Date.now()){
  if(params.has('code')||params.has('state')||params.has('error'))throw new Error('Retorno de instalación Shopify no válido.');
  const timestamp=Number(params.get('timestamp'));
  if(!Number.isInteger(timestamp)||timestamp<=0||Math.abs(now/1000-timestamp)>600)throw new Error('El enlace de Shopify ha caducado. Abre de nuevo la app desde Shopify.');
  if(!await verifyShopifyCallback(params,secret))throw new Error('Firma de instalación Shopify no válida.');
  return shopifyDomain(params.get('shop'));
}

/** Pure financial normalization. Original totals are deliberately used, never current totals. */
export function shopifyAnalyticsCallerAllowed(caller:any):boolean {
 return Boolean(caller?.active && (caller.role==='admin'||Array.isArray(caller.permissions)&&caller.permissions.includes('shopify')));
}
function amount(value:any):number { const n=Number(value?.shopMoney?.amount??0); if(!Number.isFinite(n))throw new Error('Shopify devolvió un importe no válido.');return n; }
function nodes(value:any):any[]{return value?.nodes||value?.edges?.map((e:any)=>e.node)||[];}
function sku(line:any):string{return String(line.sku||line.variant?.id||line.id);}
export function normalizeShopifyAnalyticsOrder(o:any,owner:string,store:string){
 const currency=String(o.totalPriceSet?.shopMoney?.currencyCode||'').toUpperCase();
 if(!/^[A-Z]{3}$/.test(currency))throw new Error('Shopify no devolvió una moneda válida.');
 const common={owner_id:owner,integration_account_id:store,order_id:String(o.legacyResourceId||o.id),currency};
 const order={...common,event_at:o.processedAt||o.createdAt,updated_at:o.updatedAt,gross_sales:amount(o.totalPriceSet),sales_vat:amount(o.totalTaxSet),discounts:amount(o.totalDiscountsSet),shipping_charged:amount(o.totalShippingPriceSet),cancelled:Boolean(o.cancelledAt),test:Boolean(o.test),financial_status:String(o.displayFinancialStatus||''),requires_shipping:nodes(o.lineItems).some((l:any)=>l.requiresShipping!==false)};
 const items=nodes(o.lineItems).map((l:any)=>{
  const vat=(l.taxLines||[]).reduce((sum:number,t:any)=>sum+amount(t.priceSet),0);
  const allocated=(l.discountAllocations||[]).reduce((sum:number,d:any)=>sum+amount(d.allocatedAmountSet),0);
  const discounted=l.originalTotalSet?amount(l.originalTotalSet)-allocated:amount(l.discountedTotalSet);
  const net=o.taxesIncluded?discounted-vat:discounted;
  return {...common,line_id:String(l.id),seller_sku:sku(l),variant_id:l.variant?.id||null,name:String(l.name||l.title||'Producto Shopify'),image_url:l.image?.url||null,quantity:Number(l.quantity),gross_sales:net+vat,net_sales:net,sales_vat:vat};
 });
 const refunds:any[]=[];const refundItems:any[]=[];
 for(const r of o.refunds||[]){
  if(!nodes(r.transactions).some((t:any)=>t.status==='SUCCESS'&&t.kind==='REFUND'))continue;
  const refundCommon={...common,refund_id:String(r.id),event_at:r.createdAt};
  let tax=0;
  for(const l of nodes(r.refundLineItems)){
   const vat=amount(l.totalTaxSet);tax+=vat;
   refundItems.push({...refundCommon,line_id:String(l.lineItem?.id),seller_sku:sku(l.lineItem||{}),quantity:Number(l.quantity),net_amount:amount(l.subtotalSet),tax_amount:vat});
  }
  for(const l of nodes(r.refundShippingLines))tax+=amount(l.taxAmountSet);
  // Shopify order adjustments carry signed tax changes; refunded tax is their absolute debit.
  for(const l of nodes(r.orderAdjustments))tax+=Math.abs(amount(l.taxAmountSet));
  const gross=amount(r.totalRefundedSet);
  refunds.push({...refundCommon,gross_amount:gross,tax_amount:tax,net_amount:gross-tax});
 }
 return {order,items,refunds,refundItems};
}
